class WorkspaceManager:
    def __init__(self):
        self.workspaces = {"default": {}}
        self.current = "default"

    def new(self, name):
        self.workspaces[name] = {}

    def select(self, name):
        self.current = name

    def apply(self, resource, attrs):
        self.workspaces[self.current][resource] = attrs

    def state(self):
        return self.workspaces[self.current]


wm = WorkspaceManager()
wm.apply("aws_instance.web", {"instance_type": "t2.micro"})

wm.new("staging")
wm.select("staging")
wm.apply("aws_instance.web", {"instance_type": "t3.small"})

wm.select("default")
print("default:", wm.state())
wm.select("staging")
print("staging:", wm.state())
